  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Bazedoxifene has an absolute oral bioavailability of ~6% in postmenopausal women, but this low F is attributed to extensive first-pass glucuronidation of phenolic OH groups, a metabolic liability absent in the query's anilinoquinazoline scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Raloxifene has an absolute oral bioavailability of ~2% in humans due to extensive first-pass glucuronidation of phenolic groups; the query lacks phenolic OH and belongs to a different chemical class.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Avanafil has a bioavailability of 8–10% in humans; despite a basic amine and halo-methoxy aryl, it is a PDE5 inhibitor without the anilinoquinazoline EGFR-inhibitor scaffold, so its low F is not representative of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "Tolperisone has very low oral bioavailability in humans due to rapid first-pass metabolism; it contains a piperidine but is a small flexible ketone, not an anilinoquinazoline acrylamide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%). The query is dacomitinib, an anilinoquinazoline EGFR inhibitor closely related to afatinib, which has ~70% oral bioavailability. The 7-methoxy and piperidine-acrylamide side chain preserve the high-permeability, metabolically stable characteristics of this approved oral drug class. Retrieved low-F records involve structurally unrelated scaffolds (SERMs, curcumin, avanafil, tolperisone) whose low F is driven by phenolic glucuronidation, solubility/instability, or rapid first-pass metabolism not applicable to the query; therefore they are outweighed.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query (dacomitinib) or its closest analog afatinib is present in the provided evidence set.",
    "All retrieved records report low F in structurally unrelated scaffolds; no high-F comparator from the anilinoquinazoline class is available to directly support the prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

